	//main selection logic between game modes
	always @(posedge CLOCK_50) begin
    key_pressed_prev <= any_key_pressed;
    
    if (SW[9]) begin //SW9:reset(active high)
        menu_mode <= 1;
        countdown_mode <= 0;
        game_mode <= 0;
        game_over_mode <= 0;
        countdown_value <= 2'b11;
        countdown_counter <= 0;
        counter_clock <= 0;
        key_debounce_counter <= 0;
        transitioning_from_game_over <= 0;
    end
    else if (menu_mode) begin
        transitioning_from_game_over <= 0;
        
        if (SW[0]) selected_mode <= 1; // PVP
        else       selected_mode <= 0; // PVE
        
        if (any_key_pressed && !key_pressed_prev && !transitioning_from_game_over) begin
            menu_mode <= 0;
            countdown_mode <= 1;
            countdown_value <= 2'b11;
            countdown_counter <= 0;
        end
    end
    else if (countdown_mode) begin
        if (countdown_counter >= COUNTDOWN_DELAY - 1) begin
            countdown_counter <= 0;
            if (countdown_value == 2'b00) begin // after go,game mode
                countdown_mode <= 0;
                game_mode <= 1;
            end
            else begin
                countdown_value <= countdown_value - 1;
            end
        end
        else begin
            countdown_counter <= countdown_counter + 1;
        end
    end
    else if (game_mode) begin
        if (game_over_signal) begin
            game_mode <= 0;
            game_over_mode <= 1;
            key_debounce_counter <= 0;
        end
        else if (game_counter >= 99) begin
            game_mode <= 0;
            game_over_mode <= 1;
            key_debounce_counter <= 0;
        end
    end  
    else if (game_over_mode) begin  
        if (key_debounce_counter >= KEY_DEBOUNCE_DELAY) begin
            if (any_key_pressed && !key_pressed_prev) begin
                game_over_mode <= 0;
                menu_mode <= 1;
                countdown_mode <= 0;
                game_mode <= 0;
                countdown_value <= 2'b11;
                countdown_counter <= 0;
                counter_clock <= 0;
                selected_mode <= 0;
                key_debounce_counter <= 0;
                transitioning_from_game_over <= 1;
            end
        end
        else begin
            key_debounce_counter <= key_debounce_counter + 1;
        end
    end
end


