reg [5:0] game_tick_counter = 0;
always @(posedge game_clk or posedge reset) begin
    if (reset) begin
        game_tick_counter <= 0;
        game_counter <= 0;
    end else if (game_mode) begin
        if (game_tick_counter >= 59) begin // 60 ticks = 1 second
            game_tick_counter <= 0;
            if (game_counter < 99) begin
                game_counter <= game_counter + 1;
            end
        end else begin
            game_tick_counter <= game_tick_counter + 1;
        end
    end else begin
        game_tick_counter <= 0;
    end
end
	
	

