	//COLORING
always @(*) begin
    color = bg_color;
    
    // priority
    if (menu_mode) begin
        if (in_box_pvp) begin
            color = box_pvp_color;
        end else if (in_box_pve) begin
            color = box_pve_color;
        end else begin
            color = menu_bg_color;
        end
    end
	 
    else if (countdown_mode) begin
        if (in_countdown_area) begin
            color = countdown_display_color;
        end else begin
            color = bg_color;
        end
    end
	 
    else if (game_over_mode) begin
        color = game_over_vga_color;
    end

    else begin
        if (health_block_bar_active) begin
            color = health_block_bar_color;
        end
        
        else if (in_counter_area) begin
            color = counter_display_color;
        end
        
        else if ((show_ryu_hitbox && in_ryu_hitbox) || 
                 (show_ryu_dir_hitbox && in_ryu_dir_hitbox) || 
                 (show_ken_hitbox && in_ken_hitbox) || 
                 (show_ken_dir_hitbox && in_ken_dir_hitbox)) begin
            color = HITBOX_FILL;
        end
        
        // P1 sprites
        else if (next_x >= ryu && next_x < ryu + CHAR_WIDTH &&
                 next_y >= CHAR_Y && next_y < CHAR_Y + CHAR_HEIGHT) begin
            
            if (is_ryu_hitstun_visual && sprite_valid_hitstun) begin
                color = sprite_color_hitstun;
            end else if (is_ryu_lose_visual && sprite_valid_lose) begin
                color = sprite_color_lose;
            end else if (is_ryu_blocking && sprite_valid_blockstun) begin
                color = sprite_color_blockstun;
            end else if (is_ryu_dir_attacking_visual && sprite_valid_dir_attack && 
                        sprite_color_dir_attack != 8'b00000000) begin
                color = sprite_color_dir_attack;
            end else if (is_ryu_dir_attacking_visual && show_hurtboxes && in_ryu_hurtbox) begin
                color = HURTBOX_FILL;  // hurtbox only in  key
            end else if (is_ryu_attacking_visual && sprite_valid_attack) begin
                color = sprite_color_attack;
            end else if (!is_ryu_attacking_visual && !is_ryu_dir_attacking_visual && 
                        !is_ryu_hitstun_visual && !is_ryu_blocking && 
                        !is_ryu_lose_visual && sprite_valid_idle) begin
                color = sprite_color_idle;
            end else if (show_hurtboxes && in_ryu_hurtbox) begin
                color = HURTBOX_FILL;  //  hurtbox only  in key 
            end else begin
                color = bg_color;
            end
        end
        
        // P2
        else if (next_x >= ken && next_x < ken + CHAR_WIDTH &&
                 next_y >= CHAR2_Y && next_y < CHAR2_Y + CHAR_HEIGHT) begin
            
            if (is_ken_hitstun_visual && sprite2_valid_hitstun) begin
                color = sprite2_color_hitstun;
            end else if (is_ken_lose_visual && sprite2_valid_lose) begin
                color = sprite2_color_lose;
            end else if (is_ken_blocking && sprite2_valid_blockstun) begin
                color = sprite2_color_blockstun;
            end else if (is_ken_dir_attacking_visual && sprite2_valid_dir_attack && 
                        sprite2_color_dir_attack != 8'b00000000) begin
                color = sprite2_color_dir_attack;
            end else if (is_ken_dir_attacking_visual && show_hurtboxes && in_ken_hurtbox) begin
                color = HURTBOX_FILL;  // hurtbox only in  key
            end else if (is_ken_attacking_visual && sprite2_valid_attack) begin
                color = sprite2_color_attack;
            end else if (!is_ken_attacking_visual && !is_ken_dir_attacking_visual && 
                        !is_ken_hitstun_visual && !is_ken_blocking && 
                        !is_ken_lose_visual && sprite2_valid_idle) begin
                color = sprite2_color_idle;
            end else if (show_hurtboxes && in_ken_hurtbox) begin
                color = HURTBOX_FILL;  //  hurtbox only  in key
            end else begin
                color = bg_color;
            end
        end
        
        else if ((is_ryu_dir_attacking_visual || is_ken_dir_attacking_visual) && 
                 show_hurtboxes && (in_ryu_hurtbox || in_ken_hurtbox)) begin
            color = HURTBOX_FILL;
        end
        
        else if (show_hurtboxes && (in_ryu_hurtbox || in_ken_hurtbox)) begin
            color = HURTBOX_FILL;
        end
        
        else begin
            color = bg_color;
        end
    end
end
	 
	 
reg [24:0] blink_counter = 0;
reg blink_state = 0;
parameter BLINK_DELAY = 25_000_000;

//blink counter for game over  
always @(posedge CLOCK_50) begin
    if (game_over_mode) begin
        if (blink_counter >= BLINK_DELAY - 1) begin
            blink_counter <= 0;
            blink_state <= ~blink_state;
        end else begin
            blink_counter <= blink_counter + 1;
        end
    end else begin
        blink_counter <= 0;
        blink_state <= 1; 
    end
end

wire [6:0] countdown_7seg;
	hexto7seg countdown_display_hex (
		.hexn(countdown_7seg),
		.hex(countdown_hex)
	);
	

assign LEDR[9:7] = menu_mode ? 3'b000 :  //  menu,off
                   game_over_mode ? (blink_state ? 3'b111 : 3'b000) : // game over,blink all 
                   (p1_health == 3) ? 3'b111 :   //3 health
                   (p1_health == 2) ? 3'b110 :    //2 health
                   (p1_health == 1) ? 3'b100 :    //1 health
                   3'b000; 
assign LEDR[2:0] = menu_mode ? 3'b000 :  // menu, off
                   game_over_mode ? (blink_state ? 3'b111 : 3'b000) : // game over, blink all 
                   (p2_health == 3) ? 3'b111 :   // P2: 3 health 
                   (p2_health == 2) ? 3'b110 :   // P2: 2 health 
                   (p2_health == 1) ? 3'b100 :   // P2: 1 health 
                   3'b000;                         
						 
assign LEDR[6:3] = menu_mode ? 4'b0000 :  //menu,off  
                   game_over_mode ? (blink_state ? 4'b1111 : 4'b0000) : // game over,blink all
                   4'b0000;
	
	
	wire [3:0] tens_digit = (game_counter >= 10) ? game_counter / 10 : 4'd0;
	wire [3:0] ones_digit = game_counter % 10;

	wire [6:0] tens_7seg, ones_7seg;
	wire [6:0] num_1, num_2;


	wire is_draw;
	assign is_draw = timer_limit_reached || ((p1_health == 0) && (p2_health == 0));
	
	wire [6:0] char_P = 7'b0001100;     // P
	wire [6:0] char_E = 7'b0000110;     // E  
	wire [6:0] char_q = 7'b0011000;     // q
	wire [6:0] char_dash = 7'b0111111;  // -
	wire [6:0] char_F = 7'b0001110;     // F
	wire [6:0] char_I = 7'b1001111;     // I
	wire [6:0] char_G = 7'b1000010;     // G
	wire [6:0] char_H = 7'b0001001;     // H
	wire [6:0] char_T = 7'b0000111;     // t
	wire [6:0] char_O = 7'b1000000;     // O
	
	hexto7seg tens_converter (.hexn(tens_7seg),.hex(tens_digit));
	hexto7seg ones_converter (.hexn(ones_7seg),.hex(ones_digit)); 
	hexto7seg num_1_converter (.hexn(num_1),.hex(4'd1));
	hexto7seg num_2_converter (.hexn(num_2),.hex(4'd2));

	//hex assignments for overall game logic
assign HEX0 = (menu_mode) ? 7'h7F :                    
              (countdown_mode) ? (countdown_value == 2'b00 ? char_O : countdown_7seg) :  
              (game_mode) ? 7'h7F :                    
              (game_over_mode) ? char_dash : 7'h7F;    

assign HEX1 = (menu_mode) ? 7'h7F :                    
              (countdown_mode) ? 7'h7F :               
              (game_mode) ? char_T :                   
              (game_over_mode) ? ones_7seg : 7'h7F;    

assign HEX2 = (menu_mode) ? 7'h7F :                    
              (countdown_mode) ? 7'h7F :                
              (game_mode) ? char_H :                   
              (game_over_mode) ? tens_7seg : 7'h7F;    

assign HEX3 = (menu_mode) ? 7'h7F :                    
              (countdown_mode) ? 7'h7F :               
              (game_mode) ? char_G :                   
              (game_over_mode) ? char_dash : 7'h7F;    

assign HEX4 = (menu_mode) ? char_P :                   
              (countdown_mode) ? 7'h7F :               
              (game_mode) ? char_I :                   
              (game_over_mode) ? (
                  p1_wins ? num_1 :                    
                  p2_wins ? num_2 :                    
                  char_q                               
              ) : 7'h7F;

assign HEX5 = (menu_mode) ? (selected_mode ? num_2 : num_1) :  
              (countdown_mode) ? 7'h7F :               
              (game_mode) ? char_F :                   
              (game_over_mode) ? (
                  p1_wins ? char_P :                   
                  p2_wins ? char_P :                   
                  char_E                               
              ) : 7'h7F;
//=======================================================
//  Structural coding
//=======================================================

endmodule